from __future__ import annotations

from dataclasses import dataclass

from pathlib import Path
import copy
import re
import secrets
import threading
from types import MappingProxyType
from typing import Mapping, Any


class ScopeError(ValueError):
    """A missing, malformed, or mismatched trusted execution binding."""


_HANDLE = re.compile(r"^jv_[a-f0-9]{32}$")
_IDENT = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$")


def _freeze(value: Any) -> Any:
    """Copy and recursively freeze gateway authorization data."""
    if isinstance(value, Mapping):
        return MappingProxyType({str(k): _freeze(v) for k, v in value.items()})
    if isinstance(value, (list, tuple)):
        return tuple(_freeze(v) for v in value)
    if isinstance(value, (set, frozenset)):
        return frozenset(_freeze(v) for v in value)
    return copy.deepcopy(value)


def _resources(value: Mapping[str, Any] | None) -> MappingProxyType:
    if value is None:
        value = {}
    if not isinstance(value, Mapping):
        raise ScopeError("provider_resources must be a mapping")
    # Deep copy before freezing so a model-owned mutable object cannot mutate

    # the gateway's authorization record after issue().
    return _freeze(value)


@dataclass(frozen=True, slots=True)
class Scope:
    """The complete trusted contract passed to an execution child."""

    handle: str
    customer: str
    task_id: str
    workspace: str
    provider_resources: Mapping[str, Any]

    def __post_init__(self) -> None:
        if not isinstance(self.handle, str) or not _HANDLE.fullmatch(self.handle):
            raise ScopeError("invalid opaque scope handle")
        for name, value in (("customer", self.customer), ("task_id", self.task_id)):
            if not isinstance(value, str) or not _IDENT.fullmatch(value):
                raise ScopeError(f"invalid {name}")
        path = Path(self.workspace).expanduser()
        if not path.is_absolute():
            raise ScopeError("workspace must be absolute")
        # Resolve existing portions but do not require creation at binding
        # time.  The manager creates the approved leaf before launching.
        object.__setattr__(self, "workspace", str(path))

        object.__setattr__(self, "provider_resources", _resources(self.provider_resources))


class BoundScopeRegistry:
