def broker_context(operation, customer=None):
    """Native tools consume the same broker task context as isolated tools."""
    import colleague_access
    if _execution_state is None:
        raise ValueError('Task broker unavailable')
    router = _execution_state['router']
    _, scope = router.select()
    if customer is not None and customer != scope.customer and colleague_access.session():
        raise ValueError('Manny business scope is Increase ROAS only')
    if customer is not None and customer != scope.customer and owner_session(allow_telegram=True):
        # Explicit customer knowledge/task records remain separately scoped.
        # The owner names the customer in the tool; no chat rebinding is needed.
        from javar_isolation.request_scope import RequestScopeRouter
        conversation, record = trusted_execution_request()
        if record.get('resolution') != 'owner_direct':

            raise ValueError('Explicit customer selection requires owner context')
        selected = dict(record, customer=customer, task_id=record['task_id'] + '_' + customer)
        _, scope = RequestScopeRouter(registry=router.registry,
            current_request=lambda: (conversation, selected), registrations=router.registrations,
            workspace_root=router.workspace_root, authority=router.authority).select()
    return _execution_state['authority'].authorize_native(scope, operation, customer=customer)


