def load_runtime_readers(module_path: str, customers: list[str]) -> dict[str, dict[str, Callable[[], Any]]]:
    """Load the existing broker/runtime reader factory without importing secrets."""
    spec = importlib.util.spec_from_file_location("javar_digest_runtime_readers", module_path)
    if not spec or not spec.loader:
        raise DigestError("runtime reader module unavailable")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    factory = getattr(module, "get_readers", None)
    if not callable(factory):
        raise DigestError("runtime reader module must export get_readers(customer)")
    return {customer: factory(customer) for customer in customers}


def install_schedule(*, script: str, hour: int = DEFAULT_HOUR) -> dict[str, Any]:
    """Register the native no-agent job; the lead invokes this on the assigned host."""
    from cron.jobs import create_job, list_jobs
    spec = scheduler_spec(hour=hour)
    existing = next((job for job in list_jobs(include_disabled=True)
                     if job.get("name") == spec["name"]), None)

    if existing:
        return {"job": existing, "reused": True}
    job = create_job(prompt=None, schedule=f"0 {hour} * * *", name=spec["name"],
                     repeat=None, deliver="local", script=script,
                     no_agent=True, attach_to_session=False)
    return {"job": job, "reused": False}


