        if lease is None:
            raise PermissionError('Owner stopped or cancelled sending')
        result = api(token, 'chat.postMessage', channel=channel, text=draft['text'],

                         unfurl_links='false', unfurl_media='false', parse='none')
            lease.execute('UPDATE drafts SET state=?, receipt=? WHERE id=?',
