        return {'action': 'rewrite', 'text': '[Approved message sent by Javar. Slack receipt: ' + result['ts'] + '. Confirm briefly.]'}
    except Exception:
        approval_store.finish(key, 'failed_or_uncertain')
        return {'action': 'rewrite', 'text': '[Approved send failed or delivery is uncertain. Do not retry or claim success. Tell Alex verification is needed.]'}


