def run_connected(workflow, **kwargs):
    """Run a native Composio workflow from sync code, even if this thread has a loop."""
    async def runner():
        return await connected(workflow, **kwargs)

    try:
        asyncio.get_running_loop()
    except RuntimeError:
        return asyncio.run(runner())

    box = {}

    def thread_main():
        try:
            box['value'] = asyncio.run(runner())
        except Exception as exc:
            box['exc'] = exc

    thread = threading.Thread(target=thread_main, name='composio-connected')
    thread.start()
    thread.join()
    if 'exc' in box:
        raise box['exc']
    return box['value']


