    if not self.auth_state_path or not self.auth_state_path.exists():
        return {}
    try:
        value = json.loads(self.auth_state_path.read_text())

        return value if isinstance(value, dict) else {"__invalid__": True}
    except (OSError, ValueError, TypeError):
        # A corrupt status file cannot prove that an unchanged 401 is
