def _auth_guard(self):
    if not self.auth_state_path:
        with self._auth_lock:
            yield
        return
    import fcntl
    self.auth_state_path.parent.mkdir(parents=True, exist_ok=True)
    lock_path = self.auth_state_path.with_name(self.auth_state_path.name + ".lock")
    with lock_path.open("a+") as state_lock:
        fcntl.flock(state_lock.fileno(), fcntl.LOCK_EX)
        try:
            try:
                raw = self.auth_state_path.read_text() if self.auth_state_path.exists() else ""
                value = json.loads(raw) if raw.strip() else {}
                self._auth_latch = value if isinstance(value, dict) else {"__invalid__": True}
            except (ValueError, TypeError):
                self._auth_latch = {"__invalid__": True}

