def _save_latch(self):
    if not self.auth_state_path:
        return
    self.auth_state_path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=".ghl-auth-", dir=self.auth_state_path.parent)
    try:
        with os.fdopen(fd, "w") as stream:
            stream.write(json.dumps(self._auth_latch, sort_keys=True))
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, self.auth_state_path)
    finally:
        try:
            os.unlink(temporary)
        except FileNotFoundError:
            pass

@contextmanager
def _auth_guard(self):
    if not self.auth_state_path:
        with self._auth_lock:
            yield
        return
    import fcntl

    self.auth_state_path.parent.mkdir(parents=True, exist_ok=True)
    lock_path = self.auth_state_path.with_name(self.auth_state_path.name + ".lock")
    with lock_path.open("a+") as state_lock:
        fcntl.flock(state_lock.fileno(), fcntl.LOCK_EX)
        try:
            try:
                raw = self.auth_state_path.read_text() if self.auth_state_path.exists() else ""
                value = json.loads(raw) if raw.strip() else {}
                self._auth_latch = value if isinstance(value, dict) else {"__invalid__": True}
            except (ValueError, TypeError):
                self._auth_latch = {"__invalid__": True}
            yield
        finally:
            fcntl.flock(state_lock.fileno(), fcntl.LOCK_UN)

def reset_auth_latch(self, *, scope=None):
    """Explicit operator reset; never invoked by a task or retry path."""
    with self._auth_guard():
        # Reload latest state under the same cross-process lock before
        # removing a latch written by another gateway worker.

        if self.auth_state_path:
            self._auth_latch = self._load_latch()
        if scope is None:
            self._auth_latch.clear()
        else:
            self._auth_latch.pop(self._latch_key(scope), None)
        self._save_latch()

