def _drain(self, pid: int, proc: subprocess.Popen[str]) -> None:
    assert proc.stdout
    remaining = 2 * 1024 * 1024
    try:
        while True:
            chunk = proc.stdout.read(65536)
            if not chunk:
                break
            if len(chunk) > remaining:
                self.output_truncated.add(pid)
            if remaining:
                self.outputs[pid].append(chunk[:remaining])
                remaining = max(0, remaining - len(chunk))
    finally:
        proc.stdout.close()
        self.output_done[pid].set()

