def kill(self, pid: int) -> dict:
    proc = self.procs.get(int(pid))
    if proc is None:
        raise KeyError("unknown task process")
    if proc.poll() is None:
        os.killpg(proc.pid, signal.SIGTERM)
        try:
            proc.wait(timeout=1)
        except subprocess.TimeoutExpired:
            os.killpg(proc.pid, signal.SIGKILL)
            proc.wait(timeout=1)
    return self.poll(proc.pid)

def close(self) -> dict:
    if self.proxy is not None:
        self.proxy.terminate()
        self.proxy.wait(timeout=2)
    for proc in list(self.procs.values()):
        if proc.poll() is None:
            try:
                os.killpg(proc.pid, signal.SIGTERM)
            except ProcessLookupError:
                pass
    if self.shell and self.shell.poll() is None:
        os.killpg(self.shell.pid, signal.SIGTERM)
    return {"closed": True}

