        op = req.get("op")
        if op == "exec": return self.exec(req.get("command", ""), req.get("cwd"), req.get("timeout", 300))
        if op == "spawn": return self.spawn(req.get("command", ""), req.get("cwd"))
        if op == "poll": return self.poll(req.get("pid"))
        if op == "kill": return self.kill(req.get("pid"))
        if op == "cwd": return {"cwd": self.cwd()}
        if op == "close": return self.close()
        raise ValueError("unsupported child operation")


def serve(socket_path: str, workspace: str, broker: str | None = None) -> None:
    child = Child(workspace, broker)
    child.start()
    lifetime = os.environ.get('JAVAR_LIFETIME_FD')
    if lifetime is not None:
        fd = int(lifetime)
        def gateway_lifetime():
            try:
                while os.read(fd, 1):
                    pass
            finally:
                # PID 1 exit destroys this task's PID namespace, including
                # detached grandchildren. Gateway crash cannot orphan work.
                os._exit(0)

        threading.Thread(target=gateway_lifetime, daemon=True).start()
    path = Path(socket_path)
    path.unlink(missing_ok=True)
    path.parent.mkdir(mode=0o700, parents=True, exist_ok=True)
    server = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
    server.bind(socket_path)
    os.chmod(socket_path, 0o600)
    server.listen(1)
    while True:
        conn, _ = server.accept()
        with conn, conn.makefile("rwb") as stream:
            for raw in stream:
                try:
                    request = json.loads(raw)
                    result = {"ok": True, "result": child.handle(request)}
                except Exception as exc:
                    request = locals().get("request", {})
                    result = {"ok": False, "error": str(exc), "type": type(exc).__name__}
                stream.write((json.dumps(result) + "\n").encode())
                stream.flush()
                if request.get("op") == "close":
                    return


