def tree(d):
    """Relative path -> sha256 of every regular file. .env names, pipes, links and other special files are skipped, never opened."""
    out = {}

    for base, dirs, files in os.walk(d):
        dirs[:] = [x for x in dirs if x not in SKIP_PARTS]
        for f in files:
            fp = os.path.join(base, f)
            if f in SKIP_PARTS or f.startswith(".env") or f.endswith(".env") or re.search(r"\.(bak\d*|prev|orig)$", f):
                continue  # .env names may be 1Password FIFOs: never stat-follow, open or hash them
            st = os.lstat(fp)
            if not stat.S_ISREG(st.st_mode):
                continue
            out[os.path.relpath(fp, d)] = hashlib.sha256(open(fp, "rb").read()).hexdigest()
    return out


