def sig(p):
    """Fingerprint: SKILL.md bytes + every file's relative path and size (no other reads)."""
    p = os.path.realpath(p)
    m = hashlib.md5()
    try:
        m.update(open(os.path.join(p, "SKILL.md"), "rb").read())
    except OSError:
        m.update(b"NOSKILL")
    for root, ds, fs in os.walk(p):
        ds[:] = sorted(d for d in ds if d not in ("node_modules", ".git", "__pycache__"))
        for f in sorted(fs):
            if f == ".DS_Store":
                continue
            fp = os.path.join(root, f)
            try:
                st = os.lstat(fp)

                if stat.S_ISREG(st.st_mode):
                    m.update(f"{os.path.relpath(fp, p)}:{st.st_size}".encode())
            except OSError:
                pass
    return m.hexdigest()[:10]


