def rewrite_cfg(cfg_txt, new_off, drop_off):
    blocks = re.split(r"(?m)^(?=\[\[skills\.config\]\])", cfg_txt)
    kept = []

    for b in blocks:
        m = re.search(r'path\s*=\s*"([^"]+)"', b) if b.startswith("[[skills.config]]") else None
        if m and m.group(1) in drop_off:
            continue
        kept.append(b)
    out = "".join(kept)
    have = set(re.findall(r'path\s*=\s*"([^"]+)"', out))
    add = [f"{A}/{n}/SKILL.md" for n in sorted(new_off) if f"{A}/{n}/SKILL.md" not in have]
    if add:
        if not out.endswith("\n"):
            out += "\n"
        out += "".join(f'\n[[skills.config]]\npath = "{p}"\nenabled = false\n' for p in add)
    return out, add


