@contextmanager
def send_lease(self, key):
    # Serializes STOP with Slack submission. STOP acknowledges only after an
    # in-flight submission finishes; a stopped/cancelled draft cannot resume.
    with self.connect() as db:
        db.execute('BEGIN IMMEDIATE')
        stopped = db.execute('SELECT stopped FROM controls WHERE id=1').fetchone()[0]
        row = db.execute('SELECT state FROM drafts WHERE id=?', (key,)).fetchone()
        if stopped or row is None or row[0] != 'claimed':
            yield None
        else:
            yield db

