def _rewrite_system_content(value):
    if isinstance(value, str):
        return _rewrite_skills_text(value)
    if isinstance(value, list):
        rewritten = []
        for part in value:
            if isinstance(part, dict) and isinstance(part.get("text"), str):
                part = dict(part)
                part["text"] = _rewrite_skills_text(part["text"])
            rewritten.append(part)
        return rewritten
    return value


def on_demand_skills(request=None, **kwargs):
    """Native llm_request middleware for the optional startup-context optimization."""
    if not isinstance(request, dict):
        return None
    changed = False
    updated = dict(request)
    for key in ("system", "instructions"):
        value = updated.get(key)
        rewritten = _rewrite_system_content(value)
        if rewritten != value:
            updated[key] = rewritten
            changed = True
    for key in ("messages", "input"):
        sequence = updated.get(key)
        if not isinstance(sequence, list):
            continue
        new_sequence = []

        sequence_changed = False
        for item in sequence:
            if isinstance(item, dict) and item.get("role") in {"system", "developer"}:
                new_item = dict(item)
                new_item["content"] = _rewrite_system_content(item.get("content"))
                sequence_changed |= new_item["content"] != item.get("content")
                item = new_item
            new_sequence.append(item)
        if sequence_changed:
            updated[key] = new_sequence
            changed = True
    if not changed:
        return None
    return {"request": updated, "source": "javar-inbox", "reason": "skills_on_demand"}


def _manny_profile_secrets():
    """Read the trusted launcher's sealed allowlist; never fall back to owner/global credentials."""
    raw_fd = os.environ.get('JAVAR_MANNY_SECRET_FD', '')
    if not raw_fd.isdigit():
        raise RuntimeError('profile secret channel unavailable')
    fd = int(raw_fd)
    target = os.readlink(f'/proc/self/fd/{fd}')
    if not target.startswith('/memfd:javar-manny-profile-secrets'):

        raise RuntimeError('profile secret channel identity mismatch')
    if fcntl.fcntl(fd, F_GET_SEALS) & F_SEAL_ALL != F_SEAL_ALL:
        raise RuntimeError('profile secret channel is not sealed')
    data = os.pread(fd, 65537, 0)
    if len(data) > 65536:
        raise RuntimeError('profile secret channel is oversized')
    payload = json.loads(data)
    if not isinstance(payload, dict) or set(payload) != MANNY_PROFILE_SECRET_KEYS:
        raise RuntimeError('profile secret allowlist mismatch')
    if any(not isinstance(value, str) or not value for value in payload.values()):
        raise RuntimeError('profile secret value missing')
    return payload


def _manny_secret_source():
    from agent.secret_sources.base import ErrorKind, FetchResult, SecretSource

    class MannyInMemorySecrets(SecretSource):
        name = 'javar_manny_inmemory'
        label = 'Javar Manny in-memory profile scope'
        shape = 'bulk'
        override_existing_default = True

        def fetch(self, cfg, home_path):
            try:

                return FetchResult(secrets=_manny_profile_secrets())
            except Exception:
                return FetchResult().fail('trusted in-memory profile scope unavailable', ErrorKind.AUTH_FAILED)

        def remediation(self, kind, cfg):
            return 'Restart through the reviewed Javar launcher; do not copy owner credentials.'

    return MannyInMemorySecrets()


def _default_profile_secret_source():
    """Expose only reviewed launcher-resolved values to the default profile.

    Hermes multiplexing deliberately ignores process-environment fallbacks.
    The trusted launcher already resolved these exact references from the
    assigned vault; this source passes only the fixed configured allowlist
    in memory and only for Javar's canonical default home.
    """
    from agent.secret_sources.base import ErrorKind, FetchResult, SecretSource

    class JavarDefaultInMemorySecrets(SecretSource):
        name = 'javar_default_inmemory'
        label = 'Javar default in-memory profile scope'
        shape = 'bulk'
        override_existing_default = True

        def fetch(self, cfg, home_path):
            try:
                if Path(home_path).resolve() != Path('/home/orgo/lil-smoove/home/.hermes'):
                    return FetchResult().fail(
                        'default profile scope unavailable outside canonical home',
                        ErrorKind.AUTH_FAILED)
                values = {key: os.environ[key] for key in DEFAULT_PROFILE_SECRET_KEYS
                          if isinstance(os.environ.get(key), str) and os.environ[key]}
                if not values:
                    return FetchResult().fail(
                        'trusted launcher values unavailable', ErrorKind.AUTH_FAILED)
                return FetchResult(secrets=values)
            except Exception:
                return FetchResult().fail(
                    'trusted in-memory default scope unavailable', ErrorKind.AUTH_FAILED)

        def remediation(self, kind, cfg):
            return 'Restart through the reviewed Javar launcher; do not create secret files.'

    return JavarDefaultInMemorySecrets()


