def vault_token(reference):
    result = subprocess.run(['op', 'read', reference], capture_output=True,
                            timeout=20, env=credential_environment())
    if result.returncode or not result.stdout.strip():
        stderr = result.stderr.decode(errors='replace').lower()
        code = 'vault_read_failed'
        if 'not a valid service account token' in stderr or 'invalid token' in stderr:
            code = 'vault_service_account_invalid'
        elif 'permission' in stderr or 'not authorized' in stderr or 'access' in stderr:
            code = 'vault_access_denied'
        elif 'not found' in stderr or "isn't a valid" in stderr:
            code = 'vault_reference_unavailable'
        raise InboxFailure(code)
    return result.stdout.decode().strip()


