@dataclass
class Check:
    area: str
    key: str
    status: str
    expected: Any = None
    actual: Any = None
    detail: str = ""


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def rooted(root: Path, absolute: Any) -> Path:
    if not isinstance(absolute, str) or not absolute.startswith("/"):
        raise ValueError("path must be an absolute string")
    candidate = Path(absolute)
    if ".." in candidate.parts:
        raise ValueError("path traversal is not allowed")

    return root / absolute.lstrip("/")


def source_path(root: Path, relative: Any) -> Path:
    if not isinstance(relative, str) or not relative or Path(relative).is_absolute() or ".." in Path(relative).parts:
        raise ValueError("source_path must be a relative path without traversal")
    return root / relative


def nested(data: Any, dotted: str) -> Any:
    value = data
    for part in dotted.split("."):
        if not isinstance(value, dict) or part not in value:
            raise KeyError(dotted)
        value = value[part]
    return value


def load_yaml(path: Path) -> tuple[dict[str, Any] | None, str | None]:
    try:
        import yaml  # type: ignore
    except Exception:
        try:
            value = json.loads(path.read_text(encoding="utf-8"))
        except Exception:
            return None, "PyYAML unavailable"
        return (value, None) if isinstance(value, dict) else (None, "config root must be an object")
    try:
        value = yaml.safe_load(path.read_text(encoding="utf-8"))
    except PermissionError:
        return None, "inaccessible"

    except Exception as exc:
        return None, f"unreadable: {type(exc).__name__}"
    if not isinstance(value, dict):
        return None, "config root must be an object"
    return value, None


def file_specs(manifest: dict[str, Any]) -> tuple[list[dict[str, Any]], list[Check]]:
    specs = manifest.get("files")
    if not isinstance(specs, list):
        return [], [Check("manifest", "files", "UNKNOWN", detail="files must be a list")]
    valid: list[dict[str, Any]] = []
    errors: list[Check] = []
    names: set[str] = set()
    for index, spec in enumerate(specs):
        if not isinstance(spec, dict) or not all(isinstance(spec.get(k), str) and spec.get(k) for k in ("name", "source_path", "deployed_path", "expected_sha256")):
            errors.append(Check("manifest", f"files[{index}]", "UNKNOWN", detail="malformed file specification"))
            continue
        name = spec["name"]
        if name in names:
            errors.append(Check("manifest", f"files[{index}]", "UNKNOWN", detail="duplicate file name"))
            continue
        names.add(name)

        expected = spec["expected_sha256"]
        try:
            rooted(Path("/"), spec["deployed_path"])
            source_path(Path("/"), spec["source_path"])
        except ValueError as exc:
            errors.append(Check("manifest", name, "UNKNOWN", detail=str(exc)))
            continue
        if len(expected) != 64 or any(c not in "0123456789abcdef" for c in expected.lower()):
            errors.append(Check("manifest", name, "UNKNOWN", detail="expected_sha256 must be a SHA-256 hex digest"))
            continue
        valid.append(spec)
    return valid, errors


def check_source_files(manifest: dict[str, Any], source_root: Path | None) -> list[Check]:
    specs, errors = file_specs(manifest)
    out = list(errors)
    if source_root is None:
        return out + [Check("source", spec["source_path"], "UNKNOWN", spec["expected_sha256"], None,
                            "source freshness not checked: --source-root omitted") for spec in specs]
    for spec in specs:
        expected = spec["expected_sha256"]
        try:

            source = source_path(source_root, spec["source_path"])
            actual = sha256(source)
        except FileNotFoundError:
            out.append(Check("source", spec["source_path"], "MISSING", expected, None, "source missing"))
        except (PermissionError, OSError) as exc:
            out.append(Check("source", spec["source_path"], "UNKNOWN", expected, None, f"source {type(exc).__name__}"))
        except ValueError as exc:
            out.append(Check("manifest", spec["name"], "UNKNOWN", detail=str(exc)))
        else:
            out.append(Check("source", spec["source_path"], "PASS" if actual == expected else "DRIFT",
                             expected, actual, "manifest matches source" if actual == expected else "stale manifest: reviewed source changed"))
    return out


def check_deployed_files(manifest: dict[str, Any], root: Path) -> list[Check]:
    specs, errors = file_specs(manifest)
    out = list(errors)
    for spec in specs:
        expected = spec["expected_sha256"]
        try:
            target = rooted(root, spec["deployed_path"])

            actual = sha256(target)
        except FileNotFoundError:
            out.append(Check("files", spec["name"], "MISSING", expected, None, "deployed file absent"))
        except PermissionError:
            out.append(Check("files", spec["name"], "UNKNOWN", expected, None, "inaccessible"))
        except (OSError, ValueError) as exc:
            out.append(Check("files" if isinstance(exc, OSError) else "manifest", spec["name"], "UNKNOWN", expected, None, type(exc).__name__ if isinstance(exc, OSError) else str(exc)))
        else:
            out.append(Check("files", spec["name"], "PASS" if actual == expected else "DRIFT", expected, actual, spec.get("scope", "")))
    return out


