    expected_values = spec.get("expect")
    if not isinstance(expected_values, dict):

        return [Check("manifest", "config.expect", "UNKNOWN", detail="config.expect must be an object")]
    out: list[Check] = []
    for key, expected in expected_values.items():
        if not isinstance(key, str) or key not in SAFE_CONFIG_KEYS:
