        return [], "UNKNOWN", [Check("manifest", "known_gaps", "UNKNOWN", detail="known_gaps must be a list")]
    malformed = [Check("manifest", f"known_gaps[{i}]", "UNKNOWN", detail="gap must contain id, status, and summary strings")
                 for i, gap in enumerate(gaps)
                 if not isinstance(gap, dict) or not all(isinstance(gap.get(k), str) and gap.get(k) for k in ("id", "status", "summary"))]
