def required_deployment_keys(manifest: dict[str, Any]) -> set[tuple[str, str]] | None:
    specs, errors = file_specs(manifest)
    if errors:
        return None
    config = manifest.get("config")
    jobs = manifest.get("jobs")
    session = manifest.get("session")
    if not isinstance(config, dict) or not isinstance(config.get("expect"), dict) or not isinstance(jobs, dict) or not isinstance(jobs.get("expect"), dict) or not isinstance(session, dict):

        return None
    keys = {("files", spec["name"]) for spec in specs}
    directories = manifest.get("directories", [])
    if not isinstance(directories, list):
        return None
    for directory in directories:
        if not isinstance(directory, dict) or not isinstance(directory.get("name"), str):
            return None
        keys.add(("directories", directory["name"]))
    keys.update(("config", str(key)) for key in config["expect"])
    for name, expected in jobs["expect"].items():
        if not isinstance(expected, dict):
            return None
        keys.update(("jobs", f"{name}.{field}") for field in expected)
    keys.add(("session", "effective model"))
    if session.get("binding_key") is not None:
        keys.update({("session", "owner binding"), ("session", "model override")})
    return keys


