def on_demand_skills(request=None, **kwargs):
    """Native llm_request middleware for the optional startup-context optimization."""
    if not isinstance(request, dict):
        return None
    changed = False
    updated = dict(request)
    for key in ("system", "instructions"):
        value = updated.get(key)

        rewritten = _rewrite_system_content(value)
        if rewritten != value:
            updated[key] = rewritten
            changed = True
    for key in ("messages", "input"):
        sequence = updated.get(key)
        if not isinstance(sequence, list):
            continue
        new_sequence = []
        sequence_changed = False
        for item in sequence:
            if isinstance(item, dict) and item.get("role") in {"system", "developer"}:
                new_item = dict(item)
                new_item["content"] = _rewrite_system_content(item.get("content"))
                sequence_changed |= new_item["content"] != item.get("content")
                item = new_item
            new_sequence.append(item)
        if sequence_changed:
            updated[key] = new_sequence
            changed = True
    if not changed:
        return None
    return {"request": updated, "source": "javar-inbox", "reason": "skills_on_demand"}


def _manny_profile_secrets():
    """Read the trusted launcher's sealed allowlist; never fall back to owner/global credentials."""

    raw_fd = os.environ.get('JAVAR_MANNY_SECRET_FD', '')
    if not raw_fd.isdigit():
        raise RuntimeError('profile secret channel unavailable')
    fd = int(raw_fd)
    target = os.readlink(f'/proc/self/fd/{fd}')
    if not target.startswith('/memfd:javar-manny-profile-secrets'):
        raise RuntimeError('profile secret channel identity mismatch')
    if fcntl.fcntl(fd, F_GET_SEALS) & F_SEAL_ALL != F_SEAL_ALL:
        raise RuntimeError('profile secret channel is not sealed')
    data = os.pread(fd, 65537, 0)
    if len(data) > 65536:
        raise RuntimeError('profile secret channel is oversized')
    payload = json.loads(data)
    if not isinstance(payload, dict) or set(payload) != MANNY_PROFILE_SECRET_KEYS:
        raise RuntimeError('profile secret allowlist mismatch')
    if any(not isinstance(value, str) or not value for value in payload.values()):
        raise RuntimeError('profile secret value missing')
    return payload


