def _relative_parts(path, root):

    if not isinstance(path, str) or not path.strip():
        raise ProviderDenied(CHAT_FILE_REQUIRED)
    path = path.strip()
    if path.startswith('/workspace/'):
        remainder = path[len('/workspace/'):]
        parts = PurePosixPath(remainder).parts
    elif path.startswith('/'):
        try:
            real_root = os.path.realpath(root)
            real_path = os.path.realpath(path)
        except OSError:
            raise ProviderDenied(CHAT_FILE_REQUIRED)
        if real_path == real_root or not real_path.startswith(real_root + os.sep):
            raise ProviderDenied(CHAT_FILE_REQUIRED)
        parts = PurePosixPath(os.path.relpath(real_path, real_root)).parts
    else:
        parts = PurePosixPath(path).parts
    if not parts or any(part in ('..', '.', '') for part in parts):
        raise ProviderDenied(INVALID_CHAT_PATH)
    return parts


def _read_under(root, path):
    parts = _relative_parts(path, root)
    directory = os.open(root, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        for part in parts[:-1]:

            next_fd = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=directory)
            os.close(directory); directory = next_fd
        fd = os.open(parts[-1], os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK, dir_fd=directory)
        with os.fdopen(fd, 'rb') as stream:
            info = os.fstat(stream.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size > MAX_BYTES:
                raise ProviderDenied('Upload requires a regular chat-workspace file up to 10 MiB')
            data = stream.read(MAX_BYTES + 1)
            if not data or len(data) > MAX_BYTES:
                raise ProviderDenied('Upload file is empty or larger than 10 MiB')
            return parts[-1], data
    finally:
        os.close(directory)


