def checked(root, relative):
    """Reject redirects at every component, including hard-linked files."""
    root = Path(root)
    for p in [root, *root.parents]:
        if p.is_symlink():
            raise ValueError('Redirected toolbox root denied')
    target = root
    for part in relative.parts:
        target = target / part
        if target.is_symlink():
            raise ValueError('Toolbox symlinks are not followed')

        if target.exists():
            meta = target.stat()
            if not (stat.S_ISDIR(meta.st_mode) or stat.S_ISREG(meta.st_mode)):
                raise ValueError('Only regular toolbox files are supported')
            if stat.S_ISREG(meta.st_mode) and meta.st_nlink != 1:
                raise ValueError('Toolbox hard links are not followed')
    if not target.resolve().is_relative_to(root.resolve()):
