        a = procs[a][0]
    if a == root and via_shell and rss > limit_mb * 1024 and (best is None or rss > best[1]):

            best = (pid, rss, name)
    if not best:
        return ""
    pid, rss, name = best
    if os.environ.get("CHAT_GUARD_TEST_DRYRUN"):
        return "would stop %s pid %d %.0f MB" % (name, pid, rss / 1024.0)
    try:
        os.kill(pid, signal.SIGTERM)
        for _ in range(15):
            time.sleep(0.1)
            os.kill(pid, 0)
        os.kill(pid, signal.SIGKILL)
    except ProcessLookupError:
        pass
    except Exception as e:
        log("stop failed %d %s" % (pid, e))
        return ""
    log("stopped runaway %s pid %d %.1fGB" % (name, pid, rss / 1048576.0))
    return "Stopped `%s` (pid %d, %.1f GB), a command this chat started, so the Mac doesn't run out of memory." % (
        name, pid, rss / 1048576.0)


def top_users(n=3):
    try:
        procs, groups = proc_table(), {}
        for _, (_, rss, name) in procs.items():
            key = re.sub(r" Helper.*| \(.*\)$", "", name)
            groups[key] = groups.get(key, 0) + rss
        top = sorted(groups.items(), key=lambda kv: -kv[1])[:n]

        return ", ".join("%s %.1f GB" % (k, v / 1048576.0) for k, v in top) or "unknown"
    except Exception:
        return "unknown"


