def find_key(obj, names, depth=0):
    """First value of any key in `names` (case-insensitive), searching nested dicts and lists."""
    if depth > 8:
        return None
    lower = {n.lower() for n in names}
    if isinstance(obj, dict):
        for k, v in obj.items():

            if isinstance(k, str) and k.lower() in lower:
                return v
        for v in obj.values():
            r = find_key(v, names, depth + 1)
            if r is not None:
                return r
    elif isinstance(obj, list):
        for v in obj:
            r = find_key(v, names, depth + 1)
            if r is not None:
                return r
    return None


def regex_field(text, name):
    m = re.search(r"[\"']?\b%s\b[\"']?\s*[:=]\s*[\"']?([^\"',}\s]+)" % re.escape(name), text or "",
                  re.I)
    return m.group(1) if m else None


def field(args, text, *names):
    if isinstance(args, (dict, list)):
        v = find_key(args, names)
        if v is not None:
            return v
    for n in names:
        v = regex_field(text, n)
        if v is not None:
            return v
    return None


