def upper(v):

    return str(v).strip().strip("\"'").upper() if v is not None else ""


def read_file(path, cwd=None):
    try:
        p = os.path.expanduser(path)
        if cwd and not os.path.isabs(p):
            p = os.path.join(cwd, p)
        if under_container(p):                  # never touch other apps' folders, not even to look
            return ""
        if os.path.isfile(p) and os.path.getsize(p) <= MAX_FILE_READ:
            with open(p, "r", encoding="utf-8", errors="replace") as fh:
                return fh.read()
    except Exception:
        pass
    return ""


def under_container(path):
    """True when `path` is inside ~/Library/Containers or ~/Library/Group Containers (text only)."""
    try:
        p = os.path.normpath(os.path.expanduser(str(path))).lower()   # APFS ignores case
    except Exception:
        return False
    return any(p == d or p.startswith(d + os.sep) for d in CONTAINER_DIRS)


def glob_reaches_container(path):
    """True when a glob such as ~/Library/Group* or ~/Library/* would expand into a container."""

    p = os.path.expanduser(str(path)).lower()
    lib = os.path.join(HOME, "Library").lower() + os.sep
    if not p.startswith(lib) or not any(c in p for c in "*?["):
        return False
    first = p[len(lib):].split(os.sep)[0]
    return any(fnmatch.fnmatch(name, first) for name in ("containers", "group containers"))


def resolve_literal(spec, base_dir):
    """(absolute path, "") for a path as the shell would pass it, or (None, reason).

    ~ and $HOME are expanded; any other variable or command makes the path unknowable at check time."""
    s = str(spec or "").strip()
    if not s:
        return None, "the path is empty"
    s = re.sub(r"^\$\{?HOME\}?(?=/|$)", lambda m: HOME, s)
    if "$" in s or "`" in s:
        return None, "it uses a shell variable or command"
    s = os.path.expanduser(s)
    if not os.path.isabs(s):
        if not base_dir:
            return None, "it is relative and the folder it runs in is unknown"
        s = os.path.join(base_dir, s)
    return os.path.normpath(s), ""


def read_payload(spec, base_dir):

    """(text, "") for a -d @file payload read at its literal path, or (None, reason)."""
    p, why = resolve_literal(spec, base_dir)
    if p is None:
        return None, why
    if under_container(p):
        return None, "it is inside another app's container"
    try:
        if not os.path.isfile(p):
            return None, "the file isn't there when the guard checks (write it in an earlier command)"
        if os.path.getsize(p) > MAX_FILE_READ:
            return None, "the file is over 1 MB"
        with open(p, "r", encoding="utf-8", errors="replace") as fh:
            return fh.read(), ""
    except Exception as exc:
        return None, "it can't be read (%s)" % type(exc).__name__


