def emails_in_text(text):
    """Emails in raw text, skipping ones written right after a sender or acting-user key."""
    out = set()
    for m in EMAIL_RE.finditer(text or ""):
        before = (text[max(0, m.start() - 30):m.start()]).lower()
        if re.search(r"(user|user_id|userid|from|from_email|emailfrom|sender)[\"']?\s*[:=]\s*[\"']?$",
                     before):
            continue
        out.add(m.group(0).lower())
    return out


def mime_recipients(raw):
    """To, Cc and Bcc of a base64url MIME message (Gmail API 'raw')."""
    try:

        data = base64.urlsafe_b64decode(raw + "=" * (-len(raw) % 4)).decode("utf-8", "replace")
        headers = HeaderParser().parsestr(data, headersonly=True)
        pairs = getaddresses(headers.get_all("to", []) + headers.get_all("cc", []) +
                             headers.get_all("bcc", []))
        return {a.lower() for _, a in pairs if "@" in a}
    except Exception:
        return set()


def recipients(args, text):
    out = set()

    def walk(o, key="", depth=0, inside=False):
        if depth > 8:
            return
        if isinstance(o, dict):
            for k, v in o.items():
                kl = str(k).lower()
                if SENDER_KEYS.match(kl):
                    continue
                walk(v, kl, depth + 1, inside or kl in RECIPIENT_KEYS)
        elif isinstance(o, list):
            for v in o:
                walk(v, key, depth + 1, inside)
        elif isinstance(o, str) and inside:
            out.update(e.lower() for e in EMAIL_RE.findall(o))

    if isinstance(args, (dict, list)):
        walk(args)
        raw = find_key(args, ["raw"])

        if isinstance(raw, str) and len(raw) > 20:
            out |= mime_recipients(raw)
    else:
        out |= emails_in_text(text)
        for raw in re.findall(r"[\"']raw[\"']\s*:\s*[\"']([A-Za-z0-9_=-]{20,})[\"']", text or ""):
            out |= mime_recipients(raw)
    return out


