HEREDOC_RE = re.compile(r"<<-?[ \t]*(['\"]?)([A-Za-z_][A-Za-z0-9_]*)\1")


def split_heredocs(cmd):
    """(the command without here-document bodies, [(line that opened one, body, delimiter quoted)])."""
    lines = cmd.split("\n")
    out, bodies, i = [], [], 0
    while i < len(lines):
        line = lines[i]
        out.append(line)
        i += 1
        for m in HEREDOC_RE.finditer(line):

            if m.start() > 0 and line[m.start() - 1] == "<":
                continue                                 # <<< is a here-string
            body = []
            while i < len(lines) and lines[i].strip() != m.group(2):
                body.append(lines[i])
                i += 1
            i += 1
            bodies.append((line, "\n".join(body), bool(m.group(1))))
    return "\n".join(out), bodies


def walk_segments(cmd, base_dir):
    """Simple commands in order: {"words", "dir"}. Literal cd/pushd are followed and ( ) scopes
    them, so relative paths resolve the way the shell would (None = unknown folder)."""
    toks = tokenize(cmd)
    segs, words, stack = [], [], []
    state = {"cur": base_dir}

    def flush():
        if words:
            segs.append({"words": list(words), "dir": state["cur"]})
            w = command_words(words)
            if w and os.path.basename(w[0]) in ("cd", "pushd"):
                state["cur"] = resolve_dir(next((a for a in w[1:] if not a.startswith("-")), "~"),
                                           state["cur"])

            elif w and os.path.basename(w[0]) == "popd":
                state["cur"] = None
            del words[:]

    for t in toks:
        if is_sep(t):
            flush()
            if t == "(":
                stack.append(state["cur"])
            elif t == ")" and stack:
                state["cur"] = stack.pop()
            continue
        words.append(t)
    flush()
    return segs


