    return False


def live_substitution(text):
    """True when $(...), `...`, <(...) or >(...) sits outside single quotes, where bash runs it."""
    sq = dq = esc = False
    for i, ch in enumerate(text):
        if esc:
            esc = False
            continue
        if ch == "\\" and not sq:
            esc = True
            continue
        if ch == "'" and not dq:
            sq = not sq
            continue
        if ch == '"' and not sq:
            dq = not dq
            continue
        if sq:
            continue
        if ch == "`" or (ch in "$<>" and text[i + 1:i + 2] == "("):
            return True

    return False


