    b = os.path.basename(w[0])
    if w[0] == path or w[0].endswith("/" + os.path.basename(path)) and path.endswith(w[0].lstrip("./")):
        return True
    if b in ("source", ".") or INTERPRETERS.match(b) or b in ("uv", "npx", "bunx", "pipx"):
        script = next((a for a in w[1:] if not a.startswith("-") and a not in ("run", "exec")), "")
        return bool(script) and (script == path or script.endswith(path) or path.endswith(script.lstrip("./")))

    return False


def scripts_to_scan(cmd, cwd, segs):
    """(path, folder, runs) for the script files a command names. runs is True when the command runs
    the file (or might, through xargs, eval and the like). Paths that appear only in the Director's
    record scripts' text are skipped (fix b) when nothing else can run code."""
    paths = list(dict.fromkeys(SCRIPT_RE.findall(cmd)))
    if not paths:
        return []
    if segs is None:
        return [(p, cwd, True) for p in paths]
    dynamic = has_dynamic(cmd, segs)
    out = []
    for p in paths:
        homes = [s for s in segs if any(p in w for w in s["words"])]
        if not homes:
            out.append((p, cwd, False))                    # inside a here-document: as before
            continue
        for s in homes:
            if not dynamic and is_record_segment(s):
                continue
            runs = dynamic or segment_runs_script(s, p)
            for base in (s["dir"], cwd):
                if base:
                    out.append((p, base, runs))
    return list(dict.fromkeys(out))

