def iter_slug_calls(obj, depth=0):
    """(slug, arguments, account) from Composio meta-tool inputs such as COMPOSIO_MULTI_EXECUTE_TOOL."""
    if depth > 6:

        return
    if isinstance(obj, dict):
        slug = obj.get("tool_slug") or obj.get("toolSlug")
        if isinstance(slug, str):
            args = obj.get("arguments", obj.get("args", obj.get("input", obj.get("params"))))
            account = obj.get("account") or obj.get("connected_account_id") or obj.get("connectedAccountId")
            yield slug, args, account
            return
        for v in obj.values():
            for r in iter_slug_calls(v, depth + 1):
                yield r
    elif isinstance(obj, list):
        for v in obj:
            for r in iter_slug_calls(v, depth + 1):
                yield r


def codex_bridge_internal(tool_name, tool_input):
    """True only for a codex-bridge send to an exact thread id that a clean deny list doesn't name."""
    if tool_name != CODEX_BRIDGE_SEND or not isinstance(tool_input, dict):
        return False
    tid, msg = tool_input.get("thread_id"), tool_input.get("message")
    if not isinstance(tid, str) or not isinstance(msg, str):
        return False
    tid = tid.strip().lower()

    if not THREAD_UUID.match(tid):
        return False
    try:
        with open(CODEX_BRIDGE_CONFIG, encoding="utf-8") as fh:
            deny = json.load(fh)["deny"]
        if not isinstance(deny, list) or not deny:
            return False
        denied = set()
        for entry in deny:
            d = entry["thread_id"].strip().lower()
            if not THREAD_UUID.match(d):
                return False
            denied.add(d)
    except Exception:                               # missing, unreadable or odd-shaped: ask Alex
        return False
    return tid not in denied


