def read_tail_lines(path, max_bytes):
    with open(path, "rb") as fh:
        fh.seek(0, 2)
        size = fh.tell()
        start = max(0, size - max_bytes)
        fh.seek(start)

        data = fh.read().decode("utf-8", "replace")
    lines = data.splitlines()
    if start > 0 and lines:
        lines = lines[1:]
    return lines, start == 0


def entry_text(content):
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        return " ".join(b.get("text", "") for b in content
                        if isinstance(b, dict) and b.get("type") == "text")
    return ""


def scan_transcript(path, prompt_id=None):
    """Return (latest human message or None, assistant text it answered, prompt_id seen)."""
    if not path or not os.path.isfile(path):
        return None, "", False
    for max_bytes in (4_000_000, 32_000_000, 1 << 40):
        lines, whole = read_tail_lines(path, max_bytes)
        events = []
        prompt_seen = False
        for line in lines:
            try:
                e = json.loads(line)
            except Exception:
                continue
            t = e.get("type")
            if prompt_id and e.get("promptId") == prompt_id and e.get("origin"):
                prompt_seen = True

    if t == "user":
        origin = (e.get("origin") or {}).get("kind")
        if origin == "human" and not e.get("isMeta"):
            txt = entry_text((e.get("message") or {}).get("content"))
            events.append(("human", e.get("uuid") or e.get("timestamp"), txt))
    elif t == "attachment":
        a = e.get("attachment") or {}
        if a.get("type") == "queued_command" and \
                (a.get("origin") or {}).get("kind") == "human" and not a.get("isMeta"):
            events.append(("human", e.get("uuid") or e.get("timestamp"),
                           entry_text(a.get("prompt"))))
    elif t == "assistant":
        txt = entry_text((e.get("message") or {}).get("content"))
        if txt:
            events.append(("assistant", None, txt))
idx = None
for k in range(len(events) - 1, -1, -1):
    if events[k][0] == "human":
        idx = k
        break
if idx is None and not whole:

            continue
        if idx is None:
            return None, "", prompt_seen
        ask = []
        for k in range(idx - 1, -1, -1):
            if events[k][0] == "human":
                break
            ask.append(events[k][2])
        ask.reverse()
        return {"id": events[idx][1], "text": events[idx][2]}, "\n".join(ask), prompt_seen
    return None, "", False


def is_yes(text):
    t = (text or "").strip().lower()
    if not t or NEGATIONS.search(t):
        return False
    if any(ch in t for ch in ("\U0001F44D", "✅")):
        return True
    head = " ".join(re.findall(r"[a-z0-9']+", t)[:8])
    if any(p in head for p in APPROVE_PHRASES):
        return True
    return any(w in APPROVE_WORDS for w in head.split())


def mentioned(f, haystack):
    hay = (haystack or "").lower()
    digits = re.sub(r"(?<=\d)[-\s.](?=\d)", "", hay)
    if re.search(r"\b%s\b" % re.escape(f.code[3:].lower()), hay):
        return True
    if f.projects and not all(p.lower() in hay for p in f.projects):

        return False                    # a project-scoped call needs its project named too (item 5)
    for t in f.targets:
        if t.isdigit():
            if t in digits:
                return True
        elif t in hay:
            return True
    return False


def state_file(session_id):
    name = re.sub(r"[^A-Za-z0-9_-]", "_", session_id or "none")
    return os.path.join(STATE_DIR, "state", "%s.json" % name)


def load_state(path):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except Exception:
        return {"used": []}


def save_state(path, state):
    """True when the state reached disk. decide() needs this: an unrecorded one-time yes could be
    replayed, so it denies instead of allowing."""
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        state["used"] = state.get("used", [])[-500:]
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as fh:
            json.dump(state, fh)
        os.replace(tmp, path)
        return True
    except Exception:

        return False


